import pathlib
import base64

payload_b64 = ''

cn_func = base64.b64decode(payload_b64).decode('utf-8')

f = pathlib.Path('src/pages/aimodals.js')
d = f.read_text('utf-8')

# Search for the FIRST occurrence of ANY broken buildControlNetForge variants
# including '/* --- CONTROLNET FORGE' or '/* --- CONTROLNET FORGE'
import re
match = re.search(r'/\*\s*[--]+\s*CONTROLNET FORGE', d)
if match:
    # Truncate the file right before the very first broken one
    d = d[:match.start()]

d = d + '\n' + cn_func + '\n'
f.write_text(d, 'utf-8')
